const data = $json;
const stats = data.stats;
const chatId = data.chat_id || data.user_id;

if (!chatId) {
  throw new Error('chat_id не найден!');
}

// Если нет записей
if (!data.hasRecords) {
  return {
    json: {
      chat_id: chatId,
      text: `📊 <b>Статистика за ${data.date ? data.date.slice(8)+'.'+data.date.slice(5,7)+'.'+data.date.slice(0,4) : 'сегодня'}</b>\n\nПока ничего не записано.\n\n💬 Напиши мне что съел — текстом или голосом 🎤\n\n<i>Например:</i>\n<code>овсянка 50г, банан, кофе</code>`,
      show_buttons: false
    }
  };
}

// Блок подготовки логов (дерево продуктов)
const escapeHtml = value => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const logs = (data.logs || []).map(log => ({...log,item_name:escapeHtml(log.item_name)}));
logs.sort((a, b) => {
  if (a.time < b.time) return -1;
  if (a.time > b.time) return 1;
  return 0;
});

const timeGroups = {};
logs.forEach(meal => {
  if (!timeGroups[meal.time]) { timeGroups[meal.time] = []; }
  timeGroups[meal.time].push(meal);
});

const sortedTimes = Object.keys(timeGroups).sort();

let mealsList = '';
sortedTimes.forEach((time, index) => {
  const meals = timeGroups[time];
  let treeSymbol = index === 0 ? '┌─' : (index === sortedTimes.length - 1 ? '└─' : '├─');

  mealsList += `${treeSymbol} ${time}\n`;

  const grouped = {};
  meals.forEach(meal => {
    const key = `${meal.item_name}_${meal.weight}_${meal.calories}_${meal.protein}_${meal.fats}_${meal.carbs}`;
    if (!grouped[key]) {
      grouped[key] = { ...meal, count: 0 };
    }
    grouped[key].count++;
  });

  const itemsArray = Object.values(grouped);
  itemsArray.forEach((item, itemIdx) => {
    if (item.count > 1) {
      mealsList += `│ ${item.item_name} ${item.weight}г × ${item.count}\n`;
      mealsList += `│ ${Math.round(item.calories * item.count)} ккал • Б: ${item.protein * item.count}г  Ж: ${item.fats * item.count}г  У: ${item.carbs * item.count}г\n`;
    } else {
      mealsList += `│ ${item.item_name} ${item.weight}г\n`;
      mealsList += `│ ${Math.round(item.calories)} ккал • Б: ${item.protein}г  Ж: ${item.fats}г  У: ${item.carbs}г\n`;
    }
    if (itemIdx < itemsArray.length - 1) { mealsList += `│\n`; }
  });
});

// --- СИММЕТРИЧНЫЕ УМНЫЕ БАРЫ (10 делений) ---

function getCalorieBar(percent) {
  const totalBars = 10;
  if (percent > 100 && percent <= 115) return '🟨'.repeat(totalBars);
  if (percent > 115) return '🟥'.repeat(totalBars);

  const filled = Math.min(totalBars, Math.max(0, Math.round(percent / 10)));
  return '🟩'.repeat(filled) + '⬜'.repeat(totalBars - filled);
}

function getProteinBar(percent) {
  const totalBars = 10;
  const filled = Math.min(totalBars, Math.max(0, Math.round(percent / 10)));
  const empty = totalBars - filled;
  if (percent < 70) return '🟨'.repeat(filled) + '⬜'.repeat(empty);
  return '🟩'.repeat(filled) + '⬜'.repeat(empty);
}

function getFatCarbBar(percent) {
  const totalBars = 10;
  if (percent > 100 && percent <= 120) return '🟨'.repeat(totalBars);
  if (percent > 120) return '🟥'.repeat(totalBars);

  const filled = Math.min(totalBars, Math.max(0, Math.round(percent / 10)));
  return '🟩'.repeat(filled) + '⬜'.repeat(totalBars - filled);
}

// Расчет процентов
const proteinPercent = Math.round((stats.totalProtein / stats.dailyProtein) * 100);
const fatsPercent = Math.round((stats.totalFats / stats.dailyFats) * 100);
const carbsPercent = Math.round((stats.totalCarbs / stats.dailyCarbs) * 100);

// Умная динамическая строчка калорий (твоя фича)
let calorieRow = '';
const diff = stats.dailyCalories - stats.totalCalories;

if (diff >= 0) {
  calorieRow = `🔥 <b>Калории:</b> <b>${Math.round(stats.totalCalories)}</b> / ${Math.round(stats.dailyCalories)} ккал <i>(осталось ${Math.round(diff)} ккал)</i>`;
} else {
  calorieRow = `🔥 <b>Калории:</b> <b>${Math.round(stats.totalCalories)}</b> / ${Math.round(stats.dailyCalories)} ккал <i>(перебор ${Math.round(Math.abs(diff))} ккал)</i>`;
}

// Подсчет приемов пищи
const totalMealsCount = sortedTimes.length;
const avgMeal = totalMealsCount > 0 ? Math.round(stats.totalCalories / totalMealsCount) : 0;
const lastMealTime = sortedTimes[sortedTimes.length - 1] || '—';

const now = data.date ? DateTime.fromISO(data.date, {zone:data.timezone || 'Europe/Moscow'}) : $now.setZone(data.timezone || 'Europe/Moscow');
const dateStr = now.toFormat('d MMMM', { locale: 'ru' });

// Финальная сборка сообщения
const message = `📊 <b>Статистика • ${dateStr}</b> 🍴\n\n<blockquote>${mealsList.trim()}</blockquote>\n\n<b>ИТОГО ЗА ДЕНЬ:</b>\n\n${calorieRow}\n${getCalorieBar(stats.percentage)}\n\n💪 <b>Белки:</b> <b>${stats.totalProtein}</b> / ${stats.dailyProtein} г\n${getProteinBar(proteinPercent)}\n\n🥑 <b>Жиры:</b> <b>${stats.totalFats}</b> / ${stats.dailyFats} г\n${getFatCarbBar(fatsPercent)}\n\n🌾 <b>Углеводы:</b> <b>${stats.totalCarbs}</b> / ${stats.dailyCarbs} г\n${getFatCarbBar(carbsPercent)}\n\n<blockquote>⚡️ Средний чек приёма: <b>${avgMeal} ккал</b>\n🍽 Всего приёмов пищи: <b>${totalMealsCount}</b>\n⏰ Последний: <b>${lastMealTime}</b></blockquote>`;

return {
  json: {
    chat_id: chatId,
    text: message,
    show_buttons: true
  }
};

// Получаем данные через Merge
const allItems = $input.all().flatMap(item => item.json.snapshot ? [{json:item.json.snapshot.profile}, ...item.json.snapshot.logs.map(json=>({json}))] : [item]);

// Разделяем логи и профиль
let logs = [];
let userProfile = {};

allItems.forEach(item => {
  const data = item.json;

  // Если есть item_name — это лог
  if (data.item_name) {
    logs.push(data);
  }
  // Если есть username или daily_calories — это профиль
  else if (data.username || data.daily_calories) {
    userProfile = data;
  }
});

// Суммируем калории за день
let totalCalories = 0;
let totalProtein = 0;
let totalFats = 0;
let totalCarbs = 0;

const nutrient = value => {
  const number = Number(value ?? 0);
  if (!Number.isFinite(number) || number < 0) throw new Error('Некорректные числовые данные в дневнике питания');
  return number;
};
logs = logs.map(log => ({...log, calories:nutrient(log.calories), protein:nutrient(log.protein), fats:nutrient(log.fats), carbs:nutrient(log.carbs)}));
logs.forEach(log => {
  totalCalories += log.calories;
  totalProtein += log.protein;
  totalFats += log.fats;
  totalCarbs += log.carbs;
});

// Получаем цели из профиля
const dailyCalories = userProfile.daily_calories || 2000;
const dailyProtein = userProfile.daily_protein || 150;
const dailyFats = userProfile.daily_fats || 70;
const dailyCarbs = userProfile.daily_carbs || 250;
const goalRu = userProfile.goal_ru || 'поддержание веса';

// Получаем timezone из trigger
const timezone = $('When Executed by Another Workflow').first().json.timezone ?? 'Europe/Moscow';

// Считаем процент и остаток (калории округляем до целых)
const percentage = Math.round((totalCalories / dailyCalories) * 100);
const remaining = Math.max(0, dailyCalories - Math.round(totalCalories));
const over = Math.max(0, Math.round(totalCalories) - dailyCalories);

return {
  json: {
    stats: {
      totalCalories: Math.round(totalCalories),          // Округляем калории до целых
      totalProtein: Number(totalProtein.toFixed(1)),     // Исправлено: строго 1 знак после запятой
      totalFats: Number(totalFats.toFixed(1)),           // Исправлено: строго 1 знак после запятой
      totalCarbs: Number(totalCarbs.toFixed(1)),         // Исправлено: строго 1 знак после запятой
      dailyCalories,
      dailyProtein,
      dailyFats,
      dailyCarbs,
      remaining,
      over,
      percentage
    },
    logs: logs,
    goal_ru: goalRu,
    user_id: userProfile.user_id,
    chat_id: userProfile.user_id || $('When Executed by Another Workflow').first().json.user_id,
    timezone: timezone,
    date: $('When Executed by Another Workflow').first().json.date || null,
    hasRecords: logs.length > 0
  }
};
